-- CampusO Vol 1-8 devamı: AYBÜ İşletme Fakültesi ders içerikleri — PARÇA 3/5 (veri 2/4).
-- Bu parça 72 ders içerir. PARÇA 1 (şema) daha önce çalıştırılmış olmalı.

begin;

on conflict (bolum, ders_kodu, yariyil) do update set
  ders_adi = excluded.ders_adi, t_u_l = excluded.t_u_l, tur = excluded.tur, akts = excluded.akts,
  dil = excluded.dil, duzey = excluded.duzey, ogretim_sekli = excluded.ogretim_sekli,
  amac = excluded.amac, icerik = excluded.icerik, on_kosul = excluded.on_kosul,
  dersi_veren = excluded.dersi_veren, ogrenme_ciktilari = excluded.ogrenme_ciktilari,
  haftalik_konular = excluded.haftalik_konular, sinif = excluded.sinif;

commit;